"use client";
import {ArtemisScope} from "./artemis-scope";
import View0 from "./components/kanban-board/variants/01-project";
export interface ArtemisKanbanBoardProps {className?:string;}
export function ArtemisKanbanBoard({className}:ArtemisKanbanBoardProps){return <ArtemisScope className={className}><View0/></ArtemisScope>;}

"use client";
// @zeus-internal
import { ListTodo, Plus, RotateCcw, Search, X } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
import { BoardButton as ArtemisButton } from "./01-project/board-button";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { ColumnHeader, ColumnShell, EmptyColumn } from "./01-project/column";
import { CURRENT_USER_ID, INITIAL_TASKS, type KanbanColumn, type KanbanFilter, type KanbanTask, MEMBERS, matchesFilter, matchesQuery, } from "./01-project/data";
import { Field } from "./01-project/fields";
import { CircleCheck, CircleDot } from "./01-project/icons";
import { FilterTabs } from "./01-project/filter-tabs";
import { ArtemisMorphicTooltip, ArtemisMorphicTooltipProvider } from "./01-project/morphic-tooltip";
import { DragOverlay, DropLine, type MoveKey, TaskCard } from "./01-project/task-card";
import { type DropTarget, useCardDrag } from "./01-project/use-card-drag";
import { type DialogMode, draftAssignee, type TaskDraft, TaskDialog } from "./01-project/task-dialog";
const INITIAL_COLUMNS: KanbanColumn[] = [
    { id: "planned", title: "Planned", icon: <ListTodo /> },
    { id: "building", title: "In progress", icon: <CircleDot className="art:text-primary"/> },
    { id: "ready", title: "Ready", icon: <CircleCheck className="art:text-foreground"/> },
];
const INSTRUCTIONS = "Drag anywhere on a card to move it. On touch, hold briefly before dragging; swipe to scroll. With the handle focused, use Up or Down to reorder, Left or Right to change columns, and Home or End to move to the edges. Escape cancels a drag.";
const BOARD_FADE = { duration: 0.14, ease: ARTEMIS_EASE_OUT } as const;
type FocusTarget = {
    kind: "handle" | "open";
    taskId: string;
} | {
    kind: "rename";
    columnId: string;
};
function moveTask(tasks: KanbanTask[], taskId: string, columnId: string, beforeId: string | null): KanbanTask[] {
    const task = tasks.find((t) => t.id === taskId);
    if (!task)
        return tasks;
    const rest = tasks.filter((t) => t.id !== taskId);
    const moved = { ...task, columnId };
    if (beforeId) {
        const index = rest.findIndex((t) => t.id === beforeId);
        if (index >= 0)
            return [...rest.slice(0, index), moved, ...rest.slice(index)];
    }
    let last = -1;
    rest.forEach((t, i) => {
        if (t.columnId === columnId)
            last = i;
    });
    if (last < 0)
        return [...rest, moved];
    return [...rest.slice(0, last + 1), moved, ...rest.slice(last + 1)];
}
export default function KanbanBoardProject() {
    const id = useId();
    const reduce = useReducedMotion();
    const [columns, setColumns] = useState(INITIAL_COLUMNS);
    const [tasks, setTasks] = useState(INITIAL_TASKS);
    const [filter, setFilter] = useState<KanbanFilter>("all");
    const [query, setQuery] = useState("");
    const [dialogOpen, setDialogOpen] = useState(false);
    const [dialogMode, setDialogMode] = useState<DialogMode>({
        kind: "create",
        columnId: INITIAL_COLUMNS[0].id,
        taskId: "",
    });
    const [announcement, setAnnouncement] = useState("");
    const [focusTarget, setFocusTarget] = useState<FocusTarget | null>(null);
    const [glide, setGlide] = useState(false);
    const pendingAfterDialog = useRef<FocusTarget | null>(null);
    const boardRef = useRef<HTMLElement>(null);
    const renameRefs = useRef(new Map<string, HTMLButtonElement>());
    const searchRef = useRef<HTMLInputElement>(null);
    const titleId = `${id}-title`;
    const panelId = `${id}-columns`;
    const instructionsId = `${id}-instructions`;
    const visible = useMemo(() => tasks.filter((t) => matchesFilter(t, filter, CURRENT_USER_ID) && matchesQuery(t, query, MEMBERS)), [tasks, filter, query]);
    useEffect(() => {
        if (!focusTarget)
            return;
        const root = boardRef.current;
        const el = focusTarget.kind === "rename"
            ? renameRefs.current.get(focusTarget.columnId)
            : root?.querySelector<HTMLElement>(`[data-kanban-${focusTarget.kind}="${CSS.escape(focusTarget.taskId)}"]`);
        el?.focus({ preventScroll: true });
        setFocusTarget(null);
    }, [focusTarget]);
    const setRef = useCallback((map: Map<string, HTMLButtonElement>, key: string) => (el: HTMLButtonElement | null) => {
        if (el)
            map.set(key, el);
        else
            map.delete(key);
    }, []);
    const move = (task: KanbanTask, key: MoveKey) => {
        setGlide(false);
        const colIndex = columns.findIndex((c) => c.id === task.columnId);
        const inColumn = visible.filter((t) => t.columnId === task.columnId);
        const index = inColumn.findIndex((t) => t.id === task.id);
        let targetColumn = task.columnId;
        let beforeId: string | null = null;
        if (key === "up") {
            if (index <= 0)
                return;
            beforeId = inColumn[index - 1].id;
        }
        else if (key === "down") {
            if (index >= inColumn.length - 1)
                return;
            beforeId = inColumn[index + 2]?.id ?? null;
            if (!beforeId) {
                const last = inColumn[inColumn.length - 1];
                const rest = tasks.filter((t) => t.id !== task.id);
                const lastIndex = rest.findIndex((t) => t.id === last.id);
                const next = [...rest.slice(0, lastIndex + 1), task, ...rest.slice(lastIndex + 1)];
                commitMove(next, task, task.columnId);
                return;
            }
        }
        else if (key === "home") {
            if (index <= 0)
                return;
            beforeId = inColumn[0].id;
        }
        else if (key === "end") {
            if (index >= inColumn.length - 1)
                return;
        }
        else {
            const nextIndex = colIndex + (key === "left" ? -1 : 1);
            if (nextIndex < 0 || nextIndex >= columns.length)
                return;
            targetColumn = columns[nextIndex].id;
        }
        commitMove(moveTask(tasks, task.id, targetColumn, beforeId), task, targetColumn);
    };
    const commitMove = (next: KanbanTask[], task: KanbanTask, columnId: string, refocus = true) => {
        setTasks(next);
        const column = columns.find((c) => c.id === columnId);
        const inColumn = next.filter((t) => t.columnId === columnId);
        const position = inColumn.findIndex((t) => t.id === task.id) + 1;
        setAnnouncement(`${task.title} moved to ${column?.title ?? ""}, position ${position} of ${inColumn.length}.`);
        if (refocus)
            setFocusTarget({ kind: "handle", taskId: task.id });
    };
    const drop = (task: KanbanTask, target: DropTarget) => {
        const current = tasks.find((t) => t.id === task.id) ?? task;
        const next = moveTask(tasks, current.id, target.columnId, target.beforeId);
        const order = (list: KanbanTask[]) => list.map((t) => `${t.id}:${t.columnId}`).join(",");
        if (order(next) === order(tasks))
            return;
        setGlide(true);
        commitMove(next, current, target.columnId);
    };
    const { drag, start: startDrag, suppressClick } = useCardDrag(drop, () => setAnnouncement("Move cancelled."));
    const openCreate = (columnId: string) => {
        const taskId = crypto.randomUUID();
        setDialogMode({ kind: "create", columnId, taskId });
        setDialogOpen(true);
    };
    const openEdit = (task: KanbanTask) => {
        setDialogMode({ kind: "edit", task });
        setDialogOpen(true);
    };
    const submitDialog = (draft: TaskDraft) => {
        const title = draft.title.trim();
        const description = draft.description.trim() || undefined;
        const dueDate = draft.dueDate.trim() || undefined;
        const assigneeId = draftAssignee(draft);
        if (dialogMode.kind === "create") {
            const { taskId } = dialogMode;
            const task: KanbanTask = {
                id: taskId,
                columnId: draft.columnId,
                title,
                description,
                priority: draft.priority,
                assigneeId,
                dueDate,
            };
            setTasks((prev) => [...prev, task]);
            setAnnouncement(`${title} created.`);
            pendingAfterDialog.current = { kind: "open", taskId };
        }
        else {
            const original = dialogMode.task;
            const changedColumn = original.columnId !== draft.columnId;
            setTasks((prev) => {
                const updated: KanbanTask = {
                    ...original,
                    title,
                    description,
                    priority: draft.priority,
                    assigneeId,
                    dueDate,
                    checklist: draft.checklist,
                    columnId: original.columnId,
                };
                const replaced = prev.map((t) => (t.id === original.id ? { ...updated, columnId: t.columnId } : t));
                if (!changedColumn)
                    return replaced;
                const first = replaced.find((t) => t.columnId === draft.columnId && t.id !== original.id);
                return moveTask(replaced, original.id, draft.columnId, first?.id ?? null);
            });
            setAnnouncement(`${title} updated.`);
            pendingAfterDialog.current = { kind: "open", taskId: original.id };
        }
        setDialogOpen(false);
    };
    const dropBefore = (columnId: string, taskId: string) => drag?.target?.columnId === columnId && drag.target.beforeId === taskId;
    const dropAtEnd = (columnId: string) => drag?.target?.columnId === columnId && drag.target.beforeId === null;
    const reset = () => {
        setTasks(INITIAL_TASKS);
        setColumns(INITIAL_COLUMNS);
    };
    return (<ArtemisMorphicTooltipProvider>
      <>
        <section ref={boardRef} aria-labelledby={titleId} className="art:w-full art:max-w-6xl art:bg-background art:p-3 art:text-foreground art:@min-[640px]/artemis:p-5">
          <header className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-3 art:px-1 art:pb-4">
            <div>
              <h2 id={titleId} className="art:text-xl art:font-medium">
                Release board
              </h2>
              <p className="art:mt-1 art:text-xs art:text-muted-foreground">
                {tasks.length} tasks · {columns.length} columns
              </p>
            </div>
            <div className="art:flex art:items-center art:gap-2">
              <ArtemisMorphicTooltip content="Reset board">
                <ArtemisButton hoverOnMove variant="ghost" size="icon" className="art:size-9 art:rounded-full art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring" aria-label="Reset board" onClick={reset}>
                  <RotateCcw aria-hidden className="art:size-3.5"/>
                </ArtemisButton>
              </ArtemisMorphicTooltip>
              <ArtemisButton className="art:h-9 art:px-3 art:text-xs" onClick={() => openCreate(columns[0]?.id ?? "")}>
                <Plus aria-hidden className="art:size-3.5"/>
                New task
              </ArtemisButton>
            </div>
          </header>
          <div>
            <div className="art:mb-4 art:flex art:flex-wrap art:items-center art:justify-between art:gap-3 art:px-1">
              <div className="art:max-w-full art:overflow-x-auto">
                <FilterTabs value={filter} onValueChange={setFilter} idPrefix={id} panelId={panelId}/>
              </div>
              <Field className="art:w-full art:@min-[640px]/artemis:w-60" fieldClassName="art:ring-0 art:focus-within:border-foreground/60" inputClassName={query
            ? "art:pl-10 art:pr-10 art:min-w-0 art:text-xs art:[&::-webkit-search-cancel-button]:hidden" : "art:pl-10 art:pr-3.5 art:min-w-0 art:text-xs art:[&::-webkit-search-cancel-button]:hidden"} inputRef={searchRef} type="search" aria-label="Search tasks" placeholder="Search tasks…" value={query} onChange={(event) => setQuery(event.target.value)} leading={<span className="art:pointer-events-none art:absolute art:left-3 art:top-1/2 art:flex art:-translate-y-1/2 art:items-center art:text-muted-foreground art:[&_svg]:h-4 art:[&_svg]:w-4">
                    <Search aria-hidden/>
                  </span>} trailing={query ? (<span className="art:absolute art:right-0 art:top-0 art:flex art:h-full art:items-center art:text-muted-foreground art:[&_button]:grid art:[&_button]:place-items-center art:[&_svg]:h-4 art:[&_svg]:w-4 art:[&_button]:size-9">
                      <ArtemisMorphicTooltip content="Clear search">
                        <ArtemisButton hoverOnMove variant="ghost" size="icon" className="art:size-9" aria-label="Clear task search" onClick={() => {
                setQuery("");
                searchRef.current?.focus();
            }}>
                          <X aria-hidden className="art:size-3.5"/>
                        </ArtemisButton>
                      </ArtemisMorphicTooltip>
                    </span>) : null}/>
            </div>
            <div role="tabpanel" id={panelId} aria-labelledby={`${id}-${filter}`} data-kanban-scroll="true" className="art:overflow-x-auto art:overscroll-x-contain art:pb-1">
              <motion.div key={filter} className="art:grid art:h-120 art:min-w-full art:auto-cols-[minmax(17rem,1fr)] art:grid-flow-col art:gap-3" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={reduce ? { duration: 0 } : BOARD_FADE}>
                {columns.map((column) => {
            const columnTasks = visible.filter((t) => t.columnId === column.id);
            return (<ColumnShell key={column.id} column={column} header={<ColumnHeader column={column} count={columnTasks.length} renameRef={setRef(renameRefs.current, column.id)} onRename={(title) => {
                        setColumns((prev) => prev.map((c) => (c.id === column.id ? { ...c, title } : c)));
                        setAnnouncement(`Column renamed to ${title}.`);
                    }} onEditEnd={() => setFocusTarget({ kind: "rename", columnId: column.id })} onAdd={() => openCreate(column.id)}/>}>
                      {columnTasks.length === 0 ? (<>
                          {dropAtEnd(column.id) ? <DropLine /> : null}
                          <EmptyColumn>
                            {filter === "all" && !query.trim() ? "Drop a task here" : "No matching tasks"}
                          </EmptyColumn>
                        </>) : (<>
                          {columnTasks.map((task) => (<TaskCard key={task.id} dragging={drag?.task.id === task.id} dropBefore={dropBefore(column.id, task.id)} glide={glide} onDragStart={startDrag} task={task} member={MEMBERS.find((m) => m.id === task.assigneeId)} layoutId={`${id}-task-${task.id}`} instructionsId={instructionsId} onOpen={() => {
                            if (!suppressClick.current)
                                openEdit(task);
                        }} onMove={(key) => move(task, key)}/>))}
                          {dropAtEnd(column.id) ? <DropLine /> : null}
                        </>)}
                    </ColumnShell>);
        })}
              </motion.div>
            </div>
          </div>
          <p id={instructionsId} className="art:sr-only">
            {INSTRUCTIONS}
          </p>
          <output aria-live="polite" className="art:sr-only">
            {announcement}
          </output>
        </section>
      </>
      {drag ? (<DragOverlay task={drag.task} member={MEMBERS.find((m) => m.id === drag.task.assigneeId)} width={drag.width} x={drag.x - drag.offsetX} y={drag.y - drag.offsetY}/>) : null}
      <TaskDialog open={dialogOpen} mode={dialogMode} columns={columns} members={MEMBERS} onClose={() => setDialogOpen(false)} onSubmit={submitDialog} onExitComplete={() => {
            const target = pendingAfterDialog.current;
            pendingAfterDialog.current = null;
            if (target)
                window.requestAnimationFrame(() => setFocusTarget(target));
        }}/>
    </ArtemisMorphicTooltipProvider>);
}

"use client";
// @zeus-internal
import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { forwardRef, useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { type ArtemisButtonSize, type ArtemisButtonVariant, artemisButtonClasses } from "../../../../foundations/button-classes";
import { ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
export type BoardButtonProps = Omit<HTMLMotionProps<"button">, "className"> & {
    variant?: ArtemisButtonVariant;
    size?: ArtemisButtonSize;
    className?: string;
    rounded?: string;
    hoverOnMove?: boolean;
};
const FRESH_MS = 50;
export const BoardButton = forwardRef<HTMLButtonElement, BoardButtonProps>(function BoardButton({ variant, size, className, rounded, type = "button", tabIndex = 0, hoverOnMove = false, onPointerMove, onPointerLeave, ...props }, ref) {
    const reduce = useReducedMotion();
    const [moved, setMoved] = useState(false);
    const mountedAt = useRef(0);
    const own = useRef<HTMLButtonElement | null>(null);
    const setRefs = useCallback((el: HTMLButtonElement | null) => {
        own.current = el;
        if (typeof ref === "function")
            ref(el);
        else if (ref)
            ref.current = el;
    }, [ref]);
    useLayoutEffect(() => {
        mountedAt.current = performance.now();
    }, []);
    useEffect(() => {
        const el = own.current;
        if (!el || !hoverOnMove)
            return;
        const onEnter = (event: PointerEvent) => {
            if (event.pointerType === "mouse" && performance.now() - mountedAt.current > FRESH_MS)
                setMoved(true);
        };
        el.addEventListener("pointerenter", onEnter);
        return () => el.removeEventListener("pointerenter", onEnter);
    }, [hoverOnMove]);
    const classes = artemisButtonClasses({ variant, size, className, rounded });
    if (!hoverOnMove) {
        return (<motion.button ref={ref} type={type} tabIndex={tabIndex} className={classes} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} onPointerMove={onPointerMove} onPointerLeave={onPointerLeave} {...props}/>);
    }
    return (<motion.button ref={setRefs} type={type} tabIndex={tabIndex} className={classes} animate={{ scale: moved && !reduce ? 1.01 : 1 }} whileTap={reduce ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} onPointerMove={(event) => {
            if (event.pointerType === "mouse" && !moved)
                setMoved(true);
            onPointerMove?.(event);
        }} onPointerLeave={(event) => {
            setMoved(false);
            onPointerLeave?.(event);
        }} {...props}/>);
});

"use client";
// @zeus-internal
import { Check, Pencil, Plus, X } from "lucide-react";
import { type FormEvent, type ReactNode, type Ref, useEffect, useRef, useState } from "react";
import { BoardButton as ArtemisButton } from "./board-button";
import type { KanbanColumn } from "./data";
import { Field } from "./fields";
import { ArtemisMorphicTooltip } from "./morphic-tooltip";
export function ColumnHeader({ column, count, renameRef, onRename, onEditEnd, onAdd, }: {
    column: KanbanColumn;
    count: number;
    renameRef?: Ref<HTMLButtonElement>;
    onRename: (title: string) => void;
    onEditEnd: () => void;
    onAdd: () => void;
}) {
    const [editing, setEditing] = useState(false);
    const [value, setValue] = useState(column.title);
    const inputRef = useRef<HTMLInputElement>(null);
    useEffect(() => {
        if (editing)
            inputRef.current?.focus({ preventScroll: true });
    }, [editing]);
    const startEditing = () => {
        setValue(column.title);
        setEditing(true);
    };
    const submit = (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        const title = value.trim();
        if (!title)
            return;
        setEditing(false);
        onRename(title);
        onEditEnd();
    };
    const cancel = () => {
        setEditing(false);
        onEditEnd();
    };
    return (<header className="art:flex art:min-h-16 art:shrink-0 art:items-center art:justify-between art:gap-2 art:px-3 art:py-2">
      {editing ? (<form className="art:flex art:min-w-0 art:flex-1 art:items-center art:gap-1" onSubmit={submit}>
          <Field className="art:min-w-0 art:flex-1" fieldClassName="art:ring-0 art:focus-within:border-foreground/60" inputClassName="art:pl-3.5 art:pr-3.5 art:text-sm" aria-label="Column name" inputRef={inputRef} value={value} onChange={(event) => setValue(event.target.value)} onKeyDown={(event) => {
                if (event.key === "Escape") {
                    event.preventDefault();
                    event.stopPropagation();
                    cancel();
                }
            }}/>
          <ArtemisButton type="submit" variant="ghost" size="icon" className="art:size-9 art:shrink-0" aria-label="Save column name">
            <Check aria-hidden className="art:size-4"/>
          </ArtemisButton>
          <ArtemisButton variant="ghost" size="icon" className="art:size-9 art:shrink-0" aria-label="Cancel column rename" onClick={cancel}>
            <X aria-hidden className="art:size-4"/>
          </ArtemisButton>
        </form>) : (<>
          <div className="art:flex art:min-w-0 art:items-center art:gap-2">
            <span aria-hidden="true" className="art:grid art:size-6 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground art:[&_svg]:size-3.5">
              {column.icon}
            </span>
            <h3 className="art:truncate art:text-sm art:font-medium">{column.title}</h3>
            <span className="art:font-mono art:text-xs art:tabular-nums art:text-muted-foreground">{count}</span>
          </div>
          <div className="art:flex art:shrink-0 art:items-center">
            <ArtemisMorphicTooltip content="Rename column">
              <ArtemisButton ref={renameRef} hoverOnMove variant="ghost" size="icon" className="art:size-9" aria-label={`Rename ${column.title} column`} onClick={startEditing}>
                <Pencil aria-hidden className="art:size-3.5"/>
              </ArtemisButton>
            </ArtemisMorphicTooltip>
            <ArtemisMorphicTooltip content="Add task">
              <ArtemisButton hoverOnMove variant="ghost" size="icon" className="art:size-9" aria-label={`Add task to ${column.title}`} onClick={onAdd}>
                <Plus aria-hidden className="art:size-4"/>
              </ArtemisButton>
            </ArtemisMorphicTooltip>
          </div>
        </>)}
    </header>);
}
export function ColumnShell({ column, header, children, }: {
    column: KanbanColumn;
    header: ReactNode;
    children: ReactNode;
}) {
    const [scrolled, setScrolled] = useState(false);
    return (<section data-kanban-column={column.id} aria-label={`${column.title} column`} className="art:flex art:min-h-0 art:flex-col art:bg-background">
      {header}
      <div data-kanban-cards="true" className={scrolled
            ? "art:min-h-0 art:flex-1 art:space-y-3 art:overflow-y-auto art:overscroll-contain art:px-3 art:pb-3 art:[mask-image:linear-gradient(to_bottom,transparent,black_20px,black_calc(100%_-_20px),transparent)]" : "art:min-h-0 art:flex-1 art:space-y-3 art:overflow-y-auto art:overscroll-contain art:px-3 art:pb-3 art:[mask-image:linear-gradient(to_bottom,black_calc(100%_-_20px),transparent)]"} onScroll={(event) => setScrolled(event.currentTarget.scrollTop > 0)}>
        {children}
      </div>
    </section>);
}
export function EmptyColumn({ children }: {
    children: ReactNode;
}) {
    return (<div className="art:grid art:min-h-32 art:place-items-center art:rounded-xl art:border art:border-dashed art:border-border art:px-3 art:text-center art:text-xs art:text-muted-foreground">
      {children}
    </div>);
}

// @zeus-internal
import type { ReactNode } from "react";
export type KanbanPriority = "low" | "normal" | "high";
export type KanbanMember = {
    id: string;
    name: string;
    avatarUrl?: string;
};
export type KanbanColumn = {
    id: string;
    title: string;
    icon?: ReactNode;
};
export type KanbanChecklistItem = {
    id: string;
    label: string;
    done: boolean;
};
export type KanbanTask = {
    id: string;
    columnId: string;
    title: string;
    description?: string;
    priority: KanbanPriority;
    assigneeId?: string;
    tags?: string[];
    dueDate?: string;
    checklist?: KanbanChecklistItem[];
};
export type KanbanFilter = "all" | "high" | "mine";
export const FILTERS: readonly {
    value: KanbanFilter;
    label: string;
}[] = [
    { value: "all", label: "All tasks" },
    { value: "high", label: "High priority" },
    { value: "mine", label: "Mine" },
];
export const PRIORITY_LABEL: Record<KanbanPriority, string> = {
    low: "Low",
    normal: "Normal",
    high: "High",
};
export const PRIORITY_ORDER: readonly KanbanPriority[] = ["low", "normal", "high"];
export const MEMBERS: KanbanMember[] = [
    {
        id: "member-a",
        name: "Alex Reed",
        avatarUrl: "/assets/artemis/a5badc559b706aa529b9.svg",
    },
