export function matchesQuery(task: KanbanTask, query: string, members: readonly KanbanMember[]): boolean {
    const q = query.trim().toLowerCase();
    if (!q)
        return true;
    const assignee = members.find((m) => m.id === task.assigneeId)?.name ?? "";
    return [task.title, task.description ?? "", ...(task.tags ?? []), assignee].some((field) => field.toLowerCase().includes(q));
}
export function matchesFilter(task: KanbanTask, filter: KanbanFilter, currentUserId: string): boolean {
    if (filter === "high")
        return task.priority === "high";
    if (filter === "mine")
        return task.assigneeId === currentUserId;
    return true;
}

