import { type PointerEvent as ReactPointerEvent, useCallback, useEffect, useRef, useState } from "react";
import type { KanbanTask } from "./data";
export type DropTarget = {
    columnId: string;
    beforeId: string | null;
};
export type DragSession = {
    task: KanbanTask;
    width: number;
    offsetX: number;
    offsetY: number;
