};
type Pending = {
    task: KanbanTask;
    pointerId: number;
    pointerType: string;
    startX: number;
    startY: number;
    offsetX: number;
    offsetY: number;
    width: number;
    armed: boolean;
};
const MOUSE_SLOP = 6;
const TOUCH_SLOP = 8;
const TOUCH_HOLD_MS = 250;
const EDGE_ZONE = 28;
const EDGE_STEP = 10;
function findTarget(x: number, y: number, draggedId: string): DropTarget | null {
    const column = document
        .elementsFromPoint(x, y)
        .map((el) => el.closest<HTMLElement>("[data-kanban-column]"))
        .find((el): el is HTMLElement => el !== null);
    const columnId = column?.dataset.kanbanColumn;
    if (!column || !columnId)
        return null;
    const cards = [...column.querySelectorAll<HTMLElement>("[data-kanban-task]")].filter((el) => el.dataset.kanbanTask !== draggedId);
