                return;
            const before = scroller.scrollLeft;
            if (lastX < r.left + EDGE_ZONE)
                scroller.scrollLeft = before - EDGE_STEP;
            else if (lastX > r.right - EDGE_ZONE)
                scroller.scrollLeft = before + EDGE_STEP;
            if (scroller.scrollLeft === before)
                return;
