            setDrag((prev) => (prev ? { ...prev, target } : prev));
        };
        const activate = (x: number, y: number) => {
            active = true;
            lastX = x;
            lastY = y;
            raf = window.requestAnimationFrame(autoScroll);
            pressed.focus({ preventScroll: true });
            setDrag({
                task,
                width: p.width,
                offsetX: p.offsetX,
                offsetY: p.offsetY,
                x,
                y,
                target: findTarget(x, y, task.id),
            });
        };
