            }
            e.preventDefault();
            lastX = e.clientX;
            lastY = e.clientY;
            const target = findTarget(e.clientX, e.clientY, task.id);
            setDrag((prev) => (prev ? { ...prev, x: e.clientX, y: e.clientY, target } : prev));
        };
        const finish = (commit: boolean, e?: PointerEvent) => {
            const wasActive = active;
            stop();
            if (!wasActive)
                return;
            suppressClick.current = true;
            const release = () => {
                window.setTimeout(() => {
                    suppressClick.current = false;
                }, 0);
            };
            if (e)
                release();
            else
                window.addEventListener("pointerup", release, { once: true });
            const target = commit && e ? findTarget(e.clientX, e.clientY, task.id) : null;
            setDrag(null);
            if (target)
                dropRef.current(task, target);
            else
                cancelRef.current();
        };
        const onUp = (e: PointerEvent) => {
            if (e.pointerId === p.pointerId)
                finish(true, e);
        };
        const onCancel = (e: PointerEvent) => {
            if (e.pointerId === p.pointerId)
                finish(false);
        };
        const onKey = (e: KeyboardEvent) => {
            if (e.key !== "Escape" || !active)
                return;
            e.preventDefault();
            finish(false);
        };
        const onTouchMove = (e: TouchEvent) => {
            if (active)
